import { Injectable, signal } from '@angular/core';
import { APP_CONFIG } from '../config';
import { AyahRef } from '../models';

/** Shape of `content/<edition>/tafsir/<surah>.json` (generated by scripts/build-content.mjs). */
export interface TafsirFile {
  format: 'mushaf-tafsir';
  version: 1;
  source: { name: string; origin: string; url: string; license: string; fetchedAt: string };
  surah: number;
  /** Keys are ayah numbers ("1", "2", ...). Paragraphs are separated by a blank line. */
  ayahs: Record<string, string>;
}

/** Shape of `content/<edition>/tafsir/index.json`. */
export interface TafsirIndex {
  format: 'mushaf-tafsir-index';
  version: 1;
  /** surah number -> file size in bytes. */
  sizes: Record<string, number>;
  totalBytes: number;
}

export interface TafsirSizeInfo {
  /** Size of the complete tafsir download (bytes), from index.json; null if unknown (offline, not cached). */
  totalBytes: number | null;
  /** Bytes stored in the offline cache right now. */
  cachedBytes: number;
  cachedSurahs: number;
  totalSurahs: number;
}

export const TAFSIR_CACHE_NAME = 'mushaf-tafsir-v1';
const SURAH_COUNT = 114;

/**
 * Tafsir Kemenag RI per ayah. Per-surah files (up to ~650 KB) are loaded lazily on first use,
 * kept in memory, and never prefetched by the service worker (lazy asset group "content-tafsir").
 *
 * Offline: `downloadAll()` stores every surah file in Cache Storage (`TAFSIR_CACHE_NAME`);
 * `get()` reads that cache first, then the network. Hooks for the offline sheet:
 *   - `isAllCached()` -> Promise<boolean>
 *   - `sizeInfo()`    -> Promise<TafsirSizeInfo> (show the size in MB)
 *   - `downloadAll(onProgress, signal?)` -> Promise<{ ok: number; failed: number }>
 *   - `removeAll()`   -> Promise<void>
 */
@Injectable({ providedIn: 'root' })
export class TafsirService {
  private readonly files = new Map<number, Promise<TafsirFile | null>>();
  readonly source = signal<TafsirFile['source'] | null>(null);

  /** Tafsir text for an ayah, or null when unavailable (offline before first load, missing file). */
  async get(ref: AyahRef): Promise<string | null> {
    const f = await this.load(ref.surah);
    return f?.ayahs[String(ref.ayah)] ?? null;
  }

  /** Whole surah (the tafsir reading page), or null when unavailable. */
  surah(surah: number): Promise<TafsirFile | null> {
    return this.load(surah);
  }

  private load(surah: number): Promise<TafsirFile | null> {
    let p = this.files.get(surah);
    if (!p) {
      p = this.fetchSurah(surah)
        .then((f) => {
          this.source.set(f.source);
          return f;
        })
        .catch(() => {
          this.files.delete(surah); // retry on the next request (e.g. back online)
          return null;
        });
      this.files.set(surah, p);
    }
    return p;
  }

  private async fetchSurah(surah: number): Promise<TafsirFile> {
    if (!Number.isInteger(surah) || surah < 1 || surah > SURAH_COUNT) throw new Error('surah');
    const url = surahUrl(surah);
    const cached = await this.cacheMatch(url);
    const res = cached ?? (await fetch(url));
    if (!res.ok) throw new Error(String(res.status));
    const f = (await res.json()) as TafsirFile;
    if (f.format !== 'mushaf-tafsir' || f.surah !== surah || typeof f.ayahs !== 'object')
      throw new Error('format');
    return f;
  }

  /** True when all 114 surah files are in the offline cache. */
  async isAllCached(): Promise<boolean> {
    return (await this.cachedSurahs()).length === SURAH_COUNT;
  }

  async sizeInfo(): Promise<TafsirSizeInfo> {
    const cachedList = await this.cachedSurahs();
    let cachedBytes = 0;
    const cache = await this.openCache();
    if (cache) {
      for (const n of cachedList) {
        const r = await cache.match(surahUrl(n));
        if (r) cachedBytes += (await r.arrayBuffer()).byteLength;
      }
    }
    let totalBytes: number | null = null;
    try {
      const res = await fetch(`${base()}/index.json`);
      if (res.ok) totalBytes = ((await res.json()) as TafsirIndex).totalBytes ?? null;
    } catch {
      // offline: total unknown
    }
    if (totalBytes === null && cachedList.length === SURAH_COUNT) totalBytes = cachedBytes;
    return { totalBytes, cachedBytes, cachedSurahs: cachedList.length, totalSurahs: SURAH_COUNT };
  }

  /**
   * Downloads every missing surah file into Cache Storage (concurrency 3, 2 retries each).
   * `onProgress(done, total)` counts finished surahs (including ones already cached).
   */
  async downloadAll(
    onProgress?: (done: number, total: number) => void,
    signal?: AbortSignal,
  ): Promise<{ ok: number; failed: number }> {
    const cache = await this.openCache();
    if (!cache) throw new Error('Cache Storage tidak tersedia');
    const have = new Set(await this.cachedSurahs());
    let done = have.size;
    let failed = 0;
    onProgress?.(done, SURAH_COUNT);
    const queue = Array.from({ length: SURAH_COUNT }, (_, i) => i + 1).filter((n) => !have.has(n));
    const worker = async () => {
      for (let n = queue.shift(); n !== undefined; n = queue.shift()) {
        if (signal?.aborted) return;
        let ok = false;
        for (let attempt = 0; attempt < 3 && !ok && !signal?.aborted; attempt++) {
          try {
            const url = surahUrl(n);
            const res = await fetch(url, { signal });
            if (!res.ok) throw new Error(String(res.status));
            const f = (await res.clone().json()) as TafsirFile;
            if (f.format !== 'mushaf-tafsir' || f.surah !== n) throw new Error('format');
            await cache.put(url, res);
            ok = true;
          } catch {
            if (attempt < 2) await new Promise((r) => setTimeout(r, 400 * (attempt + 1)));
          }
        }
        if (!ok) failed++;
        else done++;
        onProgress?.(done, SURAH_COUNT);
      }
    };
    await Promise.all([worker(), worker(), worker()]);
    return { ok: done, failed };
  }

  /** Deletes the offline copy (memory cache is kept; it refills from the network on demand). */
  async removeAll(): Promise<void> {
    if (typeof caches === 'undefined') return;
    try {
      await caches.delete(TAFSIR_CACHE_NAME);
    } catch {
      // ignore
    }
  }

  private async openCache(): Promise<Cache | null> {
    if (typeof caches === 'undefined' || !caches) return null;
    try {
      return await caches.open(TAFSIR_CACHE_NAME);
    } catch {
      return null;
    }
  }

  private async cacheMatch(url: string): Promise<Response | null> {
    const cache = await this.openCache();
    if (!cache) return null;
    try {
      return (await cache.match(url)) ?? null;
    } catch {
      return null;
    }
  }

  private async cachedSurahs(): Promise<number[]> {
    const cache = await this.openCache();
    if (!cache) return [];
    try {
      const out: number[] = [];
      for (const req of await cache.keys()) {
        const m = /\/tafsir\/(\d+)\.json$/.exec(req.url);
        if (m) out.push(Number(m[1]));
      }
      return out;
    } catch {
      return [];
    }
  }
}

function base(): string {
  return `${APP_CONFIG.contentBase}/${APP_CONFIG.editionId}/tafsir`;
}

function surahUrl(n: number): string {
  return `${base()}/${n}.json`;
}
